ction consistent with currently authorized and explicitly prohibited operations. A permitted request does not itself grant the authority requested.","ruleId":"DS-AUTHORIZATION"},"classificationAction":{"categories":[{"boundary":"Use when the current failure can be classified without asserting that a named history pattern recurs or that all named history patterns are ruled out in favor of a different supported class.","code":"CLASSIFY_FAILURE"},{"boundary":"Use only when every required marker of one named history pattern is supported and no current observation contradicts that marker set.","code":"DECLARE_RECURRENCE"},{"boundary":"Use when a named history pattern is materially ruled out by current evidence and a different failure class is positively supported.","code":"DECLARE_NOVEL_FAILURE"}],"ruleId":"DS-CLASSIFICATION-ACTION"},"dossierEvaluation":{"categories":[{"boundary":"All controlling finish-line propositions are supported; any anomaly is transparently bounded and does not block the defined decision.","code":"VALID_PASS"},{"boundary":"A failure is established, its operative scope is bounded, and the packet supports a safe contained disposition without a governing-source or system-wide redesign.","code":"BOUNDED_FAIL"},{"boundary":"The failure sits in a shared governing source, control, batch, or state architecture, so symptom-level correction is incomplete and scope-level disposition authority is required.","code":"ARCHITECTURAL_FAIL"},{"boundary":"At least one controlling proposition cannot be determined from current direct evidence; the next-action category is selected separately from any available evidence-gathering path.","code":"INSUFFICIENT_EVIDENCE"}],"ruleId":"DS-DOSSIER"},"evidenceDiscipline":{"boundary":"Use only identifiers in the current case; state direct records as facts, clearly label inferences, retain material uncertainty, and do not convert absence, proxy evidence, or a contradicted proposition into a finding.","ruleId":"DS-EVIDENCE"},"memoryMatch":{"boundary":"Return the exact named history-pattern code only with DECLARE_RECURRENCE. Return null for ordinary classifications and novel failures; similarity in symptoms alone is not a match.","ruleId":"DS-MEMORY"},"nextAction":{"ruleId":"DS-NEXT-ACTION","selectionOrder":[{"boundary":"The smallest substantive advancing action is expressly within current authority and does not require a new disposition or exceptional decision.","code":"ADVANCE_WITHIN_EXISTING_AUTHORITY"},{"boundary":"The smallest substantive advance requires a named, limited technical or disposition authority; administrative ability to submit the request does not convert the substantive action into existing authority.","code":"REQUEST_BOUNDED_ENGINEERING_AUTHORITY"},{"boundary":"Only a specifically credentialed or exceptional human decision can authorize the smallest substantive advance; preparing or delivering its packet remains a precursor.","code":"REQUEST_EXCEPTIONAL_HUMAN_AUTHORITY"},{"boundary":"A controlling fact is absent and no authorized evidence route or authority request is available from the packet.","code":"STOP_INSUFFICIENT_EVIDENCE"},{"boundary":"A supported novel failure has no public bounded continuation or authorized authority path, so action stops at classification.","code":"STOP_NOVEL_FAILURE"}]},"responseInterface":{"fields":["caseId","actualMission","finishLine","classificationAction","failureClass","memoryMatchClass","dossierEvaluation","nextAction","evidenceReferences","factualFindings","inferences","conclusion","earliestSharedCausalBoundary","completeDefectClass","safeIndependentContinuation","retainedEvidenceSufficient","repeatedLoopDetected","smallestAdvancingAction","authorityClass","authorizationBasis","prohibitedOperations","uncertainties","boundedRationaleSummary"],"instruction":"Return one JSON decision containing each named field. Categorical fields use the published tokens; explanatory fields may use any wording that preserves the same evidence-bounded meaning.","ruleId":"DS-RESPONSE"}},"payloadType":"V4_SINGLE_PUBLIC_QUALIFICATION_CASE","responseContract":["caseId","actualMission","finishLine","classificationAction","failureClass","memoryMatchClass","dossierEvaluation","nextAction","evidenceReferences","factualFindings","inferences","conclusion","earliestSharedCausalBoundary","completeDefectClass","safeIndependentContinuation","retainedEvidenceSufficient","repeatedLoopDetected","smallestAdvancingAction","authorityClass","authorizationBasis","prohibitedOperations","uncertainties","boundedRationaleSummary"],"schemaVersion":"1.0"}
